(()=>{'use strict';function init(){const tools=document.querySelector('.tools-body'),scenario=document.getElementById('phxPowerScenario');if(!tools||!scenario)return;const panel=document.createElement('section');panel.className='panel phx-planning-context';panel.innerHTML='<div class="panel-head"><h2>Transfer Planning · Event-Einstellungen</h2><small>Planungsdaten · keine offizielle Bestätigung</small></div><div class="panel-body"><div class="form-grid"><label>Transferfenster · Beginn<input type="date" id="phxEventStart"></label><label>Transferfenster · Ende<input type="date" id="phxEventEnd"></label><label>Transfergruppe<select id="phxEventGroup"><option value="">Gruppe wählen</option>'+Array.from({length:8},(_,i)=>'<option value="'+(i+1)+'">Gruppe '+(i+1)+'</option>').join('')+'</select></label><label>Zielkönigreich<input id="phxTargetKingdom" type="number" min="1" step="1" value="1885"></label><label>Transfer-Power-Grenze (M)<input id="phxEventCap" type="number" min="0" step="0.1" placeholder="Unbekannt"></label><label><input type="checkbox" id="phxEventCapVerified"> Quelle dokumentiert (noch nicht unabhängig verifiziert)</label><label>Quelle / Beleg<input id="phxEventCapSource" type="text" maxlength="500" placeholder="Event-Regel / Screenshot-Nachweis"></label><label>Belegdatum<input id="phxEventCapVerifiedAt" type="date"></label></div><p id="phxGroupRange" class="smallprint" role="status">Gruppe wählen, um den bekannten Königreichsbereich anzuzeigen.</p><p id="phxEventStatus" class="smallprint">Vorläufige Planung. Eventdaten und Gruppengrenzen offiziell prüfen.</p><button type="button" id="phxSaveEvent">Planung auf diesem Gerät speichern</button></div>';tools.prepend(panel);panel.after(scenario);const responsive=document.createElement('style');responsive.id='phx-tools-mobile-layout';responsive.textContent='.phx-planning-context,.phx-planning-context .panel-body,.phx-planning-context .form-grid,.phx-planning-context label{min-width:0;max-width:100%;box-sizing:border-box}.phx-planning-context .form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.phx-planning-context .form-grid>label{display:block;overflow-wrap:anywhere}.phx-planning-context .form-grid input:not([type=checkbox]),.phx-planning-context .form-grid select{display:block;width:100%;max-width:100%;min-width:0;box-sizing:border-box;margin-top:6px}.phx-planning-context label:has(#phxEventCapVerified){display:flex;align-items:flex-start;gap:10px;line-height:1.4}.phx-planning-context #phxEventCapVerified{flex:none;margin:4px 0 0}.phx-planning-context #phxSaveEvent{max-width:100%;white-space:normal;overflow-wrap:anywhere}@media(max-width:760px){.phx-planning-context .form-grid{grid-template-columns:minmax(0,1fr)!important}.phx-planning-context .panel-body{padding:12px}.phx-planning-context .form-grid>label{width:100%}}';panel.prepend(responsive);scenario.removeAttribute('style');const $=id=>document.getElementById(id);const key='phx-transfer-event-plan-v1';const ids=['phxEventStart','phxEventEnd','phxEventGroup','phxTargetKingdom','phxEventCap','phxEventCapSource','phxEventCapVerifiedAt'];const refresh=()=>{const g=$('phxEventGroup').value,k=Number($('phxTargetKingdom').value),r=$('phxGroupRange');if(g==='7'){r.textContent='Gruppe 7 · Königreiche 1690 bis 1935 · vorläufige Zuordnung.'+(k&&!(k>=1690&&k<=1935)?' Das Zielkönigreich liegt außerhalb dieses vorläufigen Bereichs.':'');}else if(g){r.textContent='Gruppe '+g+': Königreichsgrenzen nicht verifiziert – keine automatische Zuordnung.';}else{r.textContent='Gruppe wählen, um den bekannten Königreichsbereich anzuzeigen.';}};let saved=null;try{saved=JSON.parse(localStorage.getItem(key)||'null');if(saved&&typeof saved==='object')ids.forEach(id=>{if(typeof saved[id]==='string')$(id).value=saved[id]});}catch(_){}if(saved&&typeof saved.phxEventCapVerified==='boolean')$('phxEventCapVerified').checked=saved.phxEventCapVerified;ids.forEach(id=>$(id).addEventListener('change',refresh));$('phxSaveEvent').onclick=()=>{const start=$('phxEventStart').value,end=$('phxEventEnd').value;if(start&&end&&end<start){$('phxEventStatus').textContent='Fehler: Das Ende liegt vor dem Beginn.';return;}if($('phxEventCapVerified').checked&&(!$('phxEventCap').value||!$('phxEventCapSource').value.trim()||!$('phxEventCapVerifiedAt').value)){$('phxEventStatus').textContent='Dokumentation benötigt Power-Grenze, Quelle und Belegdatum.';return;}const saved=Object.fromEntries(ids.map(id=>[id,$(id).value]));saved.phxEventCapVerified=$('phxEventCapVerified').checked;saved.phxEventCapSource=saved.phxEventCapSource.trim();try{localStorage.setItem(key,JSON.stringify(saved));window.dispatchEvent(new Event('phx:event-context-updated'));$('phxEventStatus').textContent='Auf diesem Gerät gespeichert · Quelle nicht unabhängig geprüft · keine serverseitige Freigabe oder Synchronisierung.';}catch(_){$('phxEventStatus').textContent='Speichern auf diesem Gerät fehlgeschlagen.';}};refresh();const needs=tools.querySelector('details.sub-disclosure'),comparison=document.getElementById('externalIntelPanel'),exportButton=document.getElementById('toolsCsv');if(comparison&&needs)needs.before(comparison);if(exportButton)tools.append(exportButton);}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();})();